require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../lib/SafeFormula.php';Auth::requirePermission('payroll.manage','edit');$pageTitle='فیلدهای داینامیک فیش حقوقی';$adminExtraStylesheets=['/assets/css/workforce.css'];
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('اعتبار درخواست منقضی شده است.','danger');redirect('/admin/payroll-fields.php');}try{$id=(int)($_POST['id']??0);$key=trim((string)($_POST['field_key']??''));$label=trim((string)($_POST['label']??''));if(!preg_match('/^[a-z][a-z0-9_]{1,99}$/',$key)||$label==='')throw new InvalidArgumentException('کلید انگلیسی معتبر و عنوان فارسی الزامی است.');if(Database::fetch('SELECT id FROM payroll_fields WHERE field_key=? AND id<>?',[$key,$id]))throw new InvalidArgumentException('کلید فیلد تکراری است.');$type=in_array($_POST['field_type']??'',['earning','deduction','info','calculated','employer_cost'],true)?$_POST['field_type']:'info';$dataType=in_array($_POST['data_type']??'',['text','number','money','date','percent'],true)?$_POST['data_type']:'text';$calc=in_array($_POST['calculation_type']??'',['manual','formula','system'],true)?$_POST['calculation_type']:'manual';$formula=trim((string)($_POST['formula']??''));if($calc==='formula'){$keys=array_column(Database::fetchAll('SELECT field_key FROM payroll_fields WHERE id<>?',[$id]),'field_key');preg_match_all('/[a-zA-Z_][a-zA-Z0-9_]*/',$formula,$m);$unknown=array_diff(array_unique($m[0]),$keys);if($formula===''||$unknown)throw new InvalidArgumentException('فرمول خالی است یا کلید ناشناخته دارد: '.implode('، ',$unknown));SafeFormula::evaluate($formula,array_fill_keys($keys,1));}else $formula=null;$data=[$key,$label,$type,$dataType,$calc,$formula,trim((string)($_POST['default_value']??'')),isset($_POST['visible_to_employee'])?1:0,isset($_POST['visible_in_pdf'])?1:0,(int)($_POST['sort_order']??0),isset($_POST['active'])?1:0];if($id)Database::execute('UPDATE payroll_fields SET field_key=?,label=?,field_type=?,data_type=?,calculation_type=?,formula=?,default_value=?,visible_to_employee=?,visible_in_pdf=?,sort_order=?,active=?,updated_at=NOW() WHERE id=?',[...$data,$id]);else Database::execute('INSERT INTO payroll_fields(field_key,label,field_type,data_type,calculation_type,formula,default_value,visible_to_employee,visible_in_pdf,sort_order,active,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())',$data);Auth::log((int)Auth::user()['id'],$id?'payroll_field_updated':'payroll_field_created','payroll_fields',$id?:((int)Database::lastInsertId()));flash('فیلد فیش ذخیره شد.');}catch(InvalidArgumentException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){error_log('Payroll field: '.$e->getMessage());flash('ذخیره فیلد انجام نشد.','danger');}redirect('/admin/payroll-fields.php');}
$edit=isset($_GET['edit'])?Database::fetch('SELECT * FROM payroll_fields WHERE id=?',[(int)$_GET['edit']]):null;$fields=Database::fetchAll('SELECT * FROM payroll_fields ORDER BY sort_order,id');require __DIR__.'/../views/partials/admin-header.php';?>
<div class="workforce-head"><div><h1>فیلدهای داینامیک فیش</h1><p>ستون‌های Excel و قالب فیش از این فهرست ساخته می‌شوند.</p></div><a class="btn" href="/admin/payroll-periods.php">دوره‌ها</a></div><nav class="workforce-tabs"><a href="/admin/payroll-periods.php">دوره‌ها</a><a class="is-active" href="/admin/payroll-fields.php">فیلدها</a><a href="/admin/payroll-import.php">ایمپورت</a><a href="/admin/payroll-slips.php">فیش‌ها</a></nav><section class="card"><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="compact-grid"><label class="form-field"><span>کلید انگلیسی</span><input name="field_key" dir="ltr" value="<?=e($edit['field_key']??'')?>" required></label><label class="form-field"><span>عنوان</span><input name="label" value="<?=e($edit['label']??'')?>" required></label><label class="form-field"><span>نوع فیلد</span><select name="field_type"><?php foreach(['earning'=>'مزایا','deduction'=>'کسورات','info'=>'اطلاعاتی','calculated'=>'محاسباتی','employer_cost'=>'هزینه کارفرما'] as $k=>$v):?><option value="<?=$k?>" <?=($edit['field_type']??'info')===$k?'selected':''?>><?=$v?></option><?php endforeach?></select></label><label class="form-field"><span>نوع داده</span><select name="data_type"><?php foreach(['text'=>'متن','number'=>'عدد','money'=>'پول','date'=>'تاریخ','percent'=>'درصد'] as $k=>$v):?><option value="<?=$k?>" <?=($edit['data_type']??'text')===$k?'selected':''?>><?=$v?></option><?php endforeach?></select></label><label class="form-field"><span>نحوه محاسبه</span><select name="calculation_type"><?php foreach(['manual'=>'ورودی دستی','formula'=>'فرمول امن','system'=>'سیستمی'] as $k=>$v):?><option value="<?=$k?>" <?=($edit['calculation_type']??'manual')===$k?'selected':''?>><?=$v?></option><?php endforeach?></select></label><label class="form-field"><span>فرمول</span><input name="formula" dir="ltr" value="<?=e($edit['formula']??'')?>" placeholder="base_salary + bonus"></label><label class="form-field"><span>مقدار پیش‌فرض</span><input name="default_value" value="<?=e($edit['default_value']??'')?>"></label><label class="form-field"><span>ترتیب</span><input type="number" name="sort_order" value="<?=e($edit['sort_order']??0)?>"></label></div><div class="form-actions"><label class="checkbox-item"><input type="checkbox" name="visible_to_employee" <?=!isset($edit['visible_to_employee'])||(int)$edit['visible_to_employee']?'checked':''?>> نمایش به کارمند</label><label class="checkbox-item"><input type="checkbox" name="visible_in_pdf" <?=!isset($edit['visible_in_pdf'])||(int)$edit['visible_in_pdf']?'checked':''?>> نمایش در PDF</label><label class="checkbox-item"><input type="checkbox" name="active" <?=!isset($edit['active'])||(int)$edit['active']?'checked':''?>> فعال</label><button class="btn btn-primary">ذخیره</button></div></form></section><section class="card"><div class="table-wrap"><table><thead><tr><th>کلید / عنوان</th><th>نوع</th><th>محاسبه</th><th>نمایش</th><th>وضعیت</th><th></th></tr></thead><tbody><?php foreach($fields as $f):?><tr><td><code><?=e($f['field_key'])?></code><br><?=e($f['label'])?></td><td><?=e($f['field_type'].' / '.$f['data_type'])?></td><td><?=e($f['calculation_type'])?><?php if($f['formula']):?><small dir="ltr"><?=e($f['formula'])?></small><?php endif?></td><td><?=((int)$f['visible_to_employee']?'کارمند ':'').((int)$f['visible_in_pdf']?' PDF':'')?></td><td><?=(int)$f['active']?'فعال':'غیرفعال'?></td><td><a class="btn btn-small" href="?edit=<?=$f['id']?>">ویرایش</a></td></tr><?php endforeach?></tbody></table></div></section><?php require __DIR__.'/../views/partials/admin-footer.php';?>
